CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE COLLATE NOCASE, phone TEXT UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', status TEXT NOT NULL DEFAULT 'active', tier TEXT NOT NULL DEFAULT 'free', verified INTEGER NOT NULL DEFAULT 0, session_version INTEGER NOT NULL DEFAULT 0, stripe_customer_id TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decisions (actor_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, target_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, decision TEXT NOT NULL CHECK(decision IN ('like','pass')), created_at TEXT NOT NULL, PRIMARY KEY(actor_id,target_id));
CREATE TABLE IF NOT EXISTS golden_likes (sender_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, note TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(sender_id,recipient_id));
CREATE TABLE IF NOT EXISTS connections (user_low INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_high INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(user_low,user_high), CHECK(user_low < user_high));
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, sender_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, body TEXT NOT NULL, plan_json TEXT, created_at TEXT NOT NULL, read_at TEXT);
CREATE INDEX IF NOT EXISTS messages_thread ON messages(sender_id,recipient_id,created_at);
CREATE TABLE IF NOT EXISTS hidden_messages (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE, PRIMARY KEY(user_id,message_id));
CREATE TABLE IF NOT EXISTS plans (id TEXT PRIMARY KEY, host_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', place TEXT NOT NULL, starts_at TEXT NOT NULL, intent TEXT NOT NULL, capacity INTEGER NOT NULL, audience TEXT NOT NULL DEFAULT 'any', created_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS plan_attendees (plan_id TEXT NOT NULL REFERENCES plans(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(plan_id,user_id));
CREATE TABLE IF NOT EXISTS blocks (blocker_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, blocked_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(blocker_id,blocked_id));
CREATE TABLE IF NOT EXISTS reports (id TEXT PRIMARY KEY, reporter_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, reported_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, reason TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pendiente', created_at TEXT NOT NULL, reviewed_at TEXT, reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS user_settings (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_usage (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, likes INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS weekly_usage (user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, week TEXT NOT NULL, golden INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,week));
CREATE TABLE IF NOT EXISTS paypal_orders (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, tier TEXT NOT NULL, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE, approve_url TEXT, created_at TEXT NOT NULL, capture_id TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS stripe_orders (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, tier TEXT NOT NULL, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stripe_billing_sessions (id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, tier TEXT NOT NULL, status TEXT NOT NULL, request_key TEXT NOT NULL UNIQUE, subscription_id TEXT UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, tier TEXT NOT NULL, provider TEXT NOT NULL, provider_ref TEXT NOT NULL UNIQUE, status TEXT NOT NULL, started_at TEXT NOT NULL, expires_at TEXT);
